add_shortcode( 'logout_link', 'perfectpixel_logout_link_shortcode' );
add_filter( 'wp_nav_menu_objects', 'perfectpixel_logout_menu_item' );

function perfectpixel_logout_link_url( $redirect = '' ) {
	$redirect = trim( (string) $redirect );
	if ( '' === $redirect ) {
		$redirect = trim( '{{logout_redirect_url}}' );
	}
	// wp_logout_url() includes the nonce, so WordPress logs out without asking again.
	return wp_logout_url( '' !== $redirect ? $redirect : home_url( '/' ) );
}

function perfectpixel_logout_link_shortcode( $atts ) {
	if ( ! is_user_logged_in() ) {
		return '';
	}
	$atts = shortcode_atts( array( 'text' => '{{logout_link_text}}', 'redirect' => '' ), $atts, 'logout_link' );
	return '<a class="perfectpixel-logout-link" href="' . esc_url( perfectpixel_logout_link_url( $atts['redirect'] ) ) . '">' . esc_html( $atts['text'] ) . '</a>';
}

// Menu items with the URL "#logout" become a real logout link (hidden for guests).
function perfectpixel_logout_menu_item( $items ) {
	foreach ( $items as $i => $item ) {
		if ( '#logout' !== trim( (string) $item->url ) ) {
			continue;
		}
		if ( ! is_user_logged_in() ) {
			unset( $items[ $i ] );
			continue;
		}
		$item->url = perfectpixel_logout_link_url();
	}
	return $items;
}
